#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    long long w, m;
    std::cin >> w >> m;
    if (w <= 3) {
        std::cout << "YES" << std::endl;
        return 0;
    }
    int nDigits = 0;
    long long val = 1;
    std::vector<long long> bases;
    while (val <= 2e9) {
        bases.push_back(val);
        val *= w;
        nDigits++;
    }
    std::vector<int> values(nDigits, -1);
    long long curTotal = 0;
    for (int i = 0; i < nDigits; ++i) {
        curTotal -= bases[i];
    }
    bool works = false;
    outer:
    while (true) {
        int index = 0;
        while (true) {
            values[index]++;
            curTotal += bases[index];
            if (values[index] != 2) {
                if (std::abs(curTotal) == m) {
                    works = true;
                }
                break;
            }
            values[index] = -1;
            curTotal -= bases[index] * 3;
            index++;
            if (index == nDigits) break outer;
        }
    }
    std::cout << (works ? "YES" : "NO") << std::endl;
    return 0;
}
